import java.util.Arrays;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.exception.NonMonotonousSequenceException;
import org.apache.commons.math.exception.util.Localizable;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for MathUtils.normalizeAngle.
 * The method normalizes an angle 'a' to be within the range [center - PI, center + PI).
 */
public class MathUtils_normalizeAngle_TriageGen1Test {

    private static final double DELTA = 1e-12;
    private static final double TWO_PI = 2.0 * Math.PI;



    @Test
    public void testNormalizeAngle_CenterZero() {
        double center = 0.0;

        // Test positive overflow
        assertEquals(Math.PI - 0.1, MathUtils.normalizeAngle(2.0 * Math.PI + (Math.PI - 0.1), center), DELTA);

        // Test negative overflow
        assertEquals(-Math.PI + 0.1, MathUtils.normalizeAngle(-2.0 * Math.PI + (-Math.PI + 0.1), center), DELTA);

        // Test exact boundary (should wrap to -PI)
        // The formula: a - 2PI * floor((a + PI - 0)/2PI)
        // If a = PI: PI - 2PI * floor(2PI/2PI) = PI - 2PI = -PI
        assertEquals(-Math.PI, MathUtils.normalizeAngle(Math.PI, center), DELTA);
    }






}

package org.apache.commons.math.util;

import java.io.*;
