import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.exception.NonMonotonousSequenceException;
import org.apache.commons.math.exception.util.Localizable;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for MathUtils.normalizeAngle.
 * The method normalizes an angle 'a' to be within the range [center - PI, center + PI).
 */
public class MathUtils_normalizeAngle_TriageGen1Test {

    private static final double DELTA = 1e-12;
    private static final double TWO_PI = 2.0 * Math.PI;





    @Test
    public void testNormalizeAngle_NonZeroCenter() {
        double center = Math.PI; // Range should be [0, 2PI)

        // a = 0.5 * PI -> should stay 0.5 * PI
        assertEquals(0.5 * Math.PI, MathUtils.normalizeAngle(0.5 * Math.PI, center), DELTA);

        // a = 2.5 * PI -> maps to 0.5 * PI
        assertEquals(0.5 * Math.PI, MathUtils.normalizeAngle(2.5 * Math.PI, center), DELTA);

        // a = -0.5 * PI -> maps to 1.5 * PI
        // floor((-0.5PI + PI - PI)/2PI) = floor(-0.5PI/2PI) = -1
        // -0.5PI - 2PI*(-1) = 1.5PI
        assertEquals(1.5 * Math.PI, MathUtils.normalizeAngle(-0.5 * Math.PI, center), DELTA);
    }




}

