/**
 * Unit tests for MathUtils.normalizeAngle.
 * The method normalizes an angle 'a' to be within the range [center - PI, center + PI).
 */
public class MathUtils_normalizeAngle_TriageGen1Test {

    private static final double DELTA = 1e-12;
    private static final double TWO_PI = 2.0 * Math.PI;







    @Test
    public void testNormalizeAngle_LargeValues() {
        double center = 0.0;
        double a = 100.0 * TWO_PI + 0.5;
        assertEquals(0.5, MathUtils.normalizeAngle(a, center), DELTA);

        double aNeg = -100.0 * TWO_PI - 0.5;
        // -0.5 normalized to [-PI, PI) is -0.5
        assertEquals(-0.5, MathUtils.normalizeAngle(aNeg, center), DELTA);
    }


}

